import{_ as t,a as r}from"./chunks/printer-bars.CnFg_LrS.js";import{_ as a,o as s,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"Printer – Printer and cartridges","description":"Independent printer widget set with status and up to six evenly distributed cartridges.","frontmatter":{"title":"Printer – Printer and cartridges","description":"Independent printer widget set with status and up to six evenly distributed cartridges."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/printer.md","filePath":"en/projects/grafik-visual-studio/printer.md","lastUpdated":1793125707000}'),o={name:"en/projects/grafik-visual-studio/printer.md"};function d(l,e,g,c,p,h){return s(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="printer" tabindex="-1">Printer <a class="header-anchor" href="#printer" aria-label="Permalink to &quot;Printer&quot;">​</a></h1><p>From <strong>Studio 0.1.273</strong>, select <strong>Properties → WIDGET → Cartridges → Style → Cartridges / Bar</strong>. Cartridges keeps the graphics side by side; Bar displays 1–6 rows with a name, horizontal fill and percentage. Both styles use the same entities, colors and warning threshold. Missing values remain <strong>—</strong>; legacy toner selection maps to bars. Full/half cartridge size affects graphics only. <strong>Printer package 0.1.1</strong> includes the corrected selection; existing 0.1.0 packages also work with the updated Studio.</p><p><strong>Printer 0.1.1</strong> is an independent external widget set by <strong>rockbaer2007</strong>. The style selection shown here requires <strong>Grafik Visual Studio 0.1.273 or newer</strong>. It displays a printer with its current status and <strong>1–6 ink or toner levels</strong>, using cartridge graphics or horizontal bars.</p><h3 id="style-cartridges" tabindex="-1">Style: Cartridges <a class="header-anchor" href="#style-cartridges" aria-label="Permalink to &quot;Style: Cartridges&quot;">​</a></h3><p>The screenshot shows the runtime with test data.</p><p><img src="'+t+'" alt="Printer with six cartridges and a low-level warning"></p><h3 id="style-bar" tabindex="-1">Style: Bar <a class="header-anchor" href="#style-bar" aria-label="Permalink to &quot;Style: Bar&quot;">​</a></h3><p>Under <strong>Properties → WIDGET → Cartridges → Style</strong>, select <strong>Bar</strong>. The runtime screenshot below uses six supplies with test data: <strong>Yellow at 18%</strong> is below the 20% warning threshold and is highlighted. <strong>Gray</strong> has no reading, so its bar is hatched and displays <strong>—</strong> rather than an invented percentage. This screenshot uses the German interface.</p><p><img src="'+r+'" alt="Printer with six horizontal bars, a low yellow supply warning and an unknown gray level"></p><h2 id="original-project" tabindex="-1">Original project <a class="header-anchor" href="#original-project" aria-label="Permalink to &quot;Original project&quot;">​</a></h2><p>Inspired by <a href="https://github.com/ADNPolymerase/ha-printer-card" target="_blank" rel="noreferrer">HA Printer Card by ADNPolymerase</a>, published under the <a href="https://github.com/ADNPolymerase/ha-printer-card/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT license</a>. The original is a Lovelace card. Printer uses original SVG artwork, its own Studio renderer and explicitly selected Home Assistant entities. No upstream source or artwork is bundled. It appears as a separate palette set and does not belong to Industrial.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li>Update Grafik Visual Studio to <strong>0.1.273 or newer</strong>.</li><li><a href="https://raw.githubusercontent.com/rockbaer2007/ugso-ha-mqtt-addons/master/ha_grafik_visual_studio/packages/printer/ugso.printer.wg" target="_blank" rel="noreferrer">Download ugso.printer.wg</a>.</li><li>Install under <strong>Settings → Widget packages → Local</strong>.</li><li>Add <strong>Printer → Drucker</strong> from the palette and select status and supply entities using <strong>…</strong>.</li></ol><p>The package contains one declarative widget definition, an original palette icon, instructions and an MIT license. It contains no executable package code. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/printer" target="_blank" rel="noreferrer">Source and package instructions</a>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>From Studio <strong>0.1.270</strong>, <strong>Properties → WIDGET</strong> also provides <strong>CSS Font &amp; Text</strong>, <strong>CSS background</strong>, <strong>CSS borders</strong>, and <strong>CSS shadow and spacing</strong>, alongside <strong>General CSS</strong>. New groups start disabled. Enable their checkbox to configure fonts, background/image, border color/width/style, one radius for all corners (<strong>0 = square</strong>), shadows and spacing. CSS styles the visible printer card rather than a hidden surface behind it. Status and supply colors retain their own settings. Existing packages remain compatible.</p><table tabindex="0"><thead><tr><th>Section</th><th>Settings</th></tr></thead><tbody><tr><td>Printer</td><td>Caption, status entity, model <code>mfp</code> (multifunction), <code>inkjet</code> or <code>office</code>.</td></tr><tr><td>Cartridges</td><td>Count <strong>1–6</strong>, <strong>Style → Cartridges / Bar</strong>, low threshold <strong>0–100 %</strong>, default <strong>20 %</strong>.</td></tr><tr><td>Cartridge 1–6</td><td>Individual percentage entity, caption and color. The first N entries are active. Later bindings remain saved and are polled again when the count is increased.</td></tr><tr><td>Status message</td><td>Optional display. Separate entity, otherwise the printer entity&#39;s <code>state_message</code> or <code>state_reason</code>.</td></tr><tr><td>Additional values</td><td>Optional power and page-counter entities.</td></tr><tr><td>Colors and size</td><td>Background, text and printing-state color. Default <strong>480 × 440 px</strong>, minimum <strong>240 × 280 px</strong>.</td></tr></tbody></table><p>The count determines distribution; individual cartridge X positions are unnecessary. Long captions are truncated when space is limited. Tooltips retain full names and values. From <strong>Studio 0.1.263</strong>, properties only show the selected cartridges: a count of 4 shows groups <strong>Cartridge 1–4</strong>, a count of 5 shows <strong>Cartridge 1–5</strong>. Hidden cartridge settings remain saved and reappear when the count increases.</p><h2 id="status-and-readings" tabindex="-1">Status and readings <a class="header-anchor" href="#status-and-readings" aria-label="Permalink to &quot;Status and readings&quot;">​</a></h2><p>Language follows the Studio <strong>DE/EN</strong> setting automatically, including automatic selection from Home Assistant. There is no separate widget language selector. Status labels, hints and properties are translated; custom captions, model names and entity messages remain unchanged.</p><p>Common states map to ready, printing, sleep, warning, stopped, offline or unknown. While printing, the sheet moves and the LED blinks. Browser reduced-motion preferences disable these animations. Errors and jams take priority; a supply warning alone does not stop the printing animation.</p><p>Editor and runtime read the same current Home Assistant values. Missing or invalid levels display <strong>—</strong>, rather than 0 %. Valid numbers are clamped to <strong>0–100 %</strong>. At or below the threshold, the cartridge and its reading are highlighted, with affected names listed below.</p><h2 id="custom-printer-photo-and-cartridge-size" tabindex="-1">Custom printer photo and cartridge size <a class="header-anchor" href="#custom-printer-photo-and-cartridge-size" aria-label="Permalink to &quot;Custom printer photo and cartridge size&quot;">​</a></h2><p><strong>Studio 0.1.262</strong> adds a model name, <strong>Standard graphic / Custom image</strong> selection and a printer photo field accepting a URL or <code>/local/...</code> path. Entering an image path automatically enables the custom photo, including URLs without a file extension. <strong>Upload image</strong> embeds a PNG, JPEG, WebP, GIF or SVG file up to 2 MB in the saved project. URL and <code>/local/...</code> sources must also be accessible in the runtime.</p><p>The photo keeps its aspect ratio and falls back to the standard drawing if missing or unavailable. Status and supplies remain active; the sheet animation belongs to the standard drawing. <strong>Cartridge size</strong> offers <strong>Full size / Half size</strong>, defaulting to half size. Labels and percentages retain their size. Existing Printer packages receive these settings when Studio is updated; reinstalling the package is unnecessary.</p><h2 id="printer-web-interface" tabindex="-1">Printer web interface <a class="header-anchor" href="#printer-web-interface" aria-label="Permalink to &quot;Printer web interface&quot;">​</a></h2><p>The web interface URL field displays a <strong>Web ↗</strong> link. A manually entered URL takes priority. <code>auto</code> uses the first HTTP/HTTPS address in the status entity&#39;s <code>configuration_url</code>, <code>web_url</code>, <code>url</code>, <code>device_url</code> or <code>printer_uri</code> attribute. Without a matching address the link stays hidden; no device discovery is performed. An empty field also hides it. The web interface opens in a new tab.</p><h2 id="scope-of-this-version" tabindex="-1">Scope of this version <a class="header-anchor" href="#scope-of-this-version" aria-label="Permalink to &quot;Scope of this version&quot;">​</a></h2><p>This first version uses explicitly selected entities. It has no automatic device/supply discovery, wear parts, socket control or test printing. All bindings are read-only. The separately available original card offers further features.</p>',29)])])}const f=a(o,[["render",d]]);export{b as __pageData,f as default};
